:root {
  color-scheme: dark;
  font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
  font-size: 16px;
  background: #142c35;
  color: #f4f0df;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: repeating-linear-gradient(135deg, #183943 0 18px, #16343d 18px 36px);
}
.board {
  width: min(760px, 100%);
  padding: clamp(20px, 5vw, 40px);
  background: #203e47;
  border: 4px solid #0d2028;
  box-shadow: 8px 8px 0 #0d2028;
}
.board-header, .board-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.eyebrow, .clock-label, th, .board-footer p { color: #9db5ae; font-size: .85rem; letter-spacing: .12em; }
.eyebrow { margin: 0 0 8px; }
h1 { margin: 0; font-size: clamp(1.8rem, 6vw, 2.5rem); letter-spacing: .03em; }
.clock-box { text-align: right; padding: 10px 14px; border: 2px solid #47636a; background: #152f38; }
.clock-label { display: block; font-size: .7rem; }
#clock { display: block; margin-top: 4px; color: #f2c66d; font-size: 1.6rem; font-weight: 700; font-variant-numeric: tabular-nums; }
.table-wrap { margin: 28px 0 24px; overflow-x: auto; }
table { width: 100%; border-collapse: collapse; text-align: left; }
th { padding: 0 10px 12px; }
td { padding: 16px 10px; border-top: 2px solid #36545b; font-size: 1rem; }
td:first-child { font-weight: 700; }
td:nth-child(2) { font-variant-numeric: tabular-nums; }
.status { color: #9db5ae; font-size: .8rem; letter-spacing: .05em; white-space: nowrap; }
tr.next { background: #354b3e; box-shadow: inset 4px 0 #f2c66d; }
tr.next .status { color: #f2c66d; font-weight: 700; }
tr.departed { color: #839393; }
tr.departed .status { color: #839393; }
.board-footer { border-top: 2px solid #36545b; padding-top: 20px; }
.board-footer p { margin: 0; display: flex; align-items: center; gap: 9px; }
.legend-dot { width: 10px; height: 10px; background: #f2c66d; display: inline-block; }
button { font: inherit; font-size: 1rem; font-weight: 700; color: #142c35; background: #f2c66d; border: 3px solid #f2c66d; padding: 12px 16px; cursor: pointer; transition: transform .08s, background .15s, color .15s; }
button:hover { background: #ffda8c; border-color: #ffda8c; }
button:focus-visible { outline: 3px solid #f4f0df; outline-offset: 4px; }
button:active { transform: translateY(2px); background: #d8ad55; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 520px) {
  body { padding: 16px 12px; }
  .board { padding: 20px 14px; box-shadow: 5px 5px 0 #0d2028; }
  .board-header { align-items: flex-start; }
  th, td { padding-left: 6px; padding-right: 6px; }
  th { font-size: .72rem; letter-spacing: .04em; }
  td { font-size: .9rem; }
  .status { font-size: .7rem; }
  .board-footer { align-items: flex-start; flex-direction: column; }
  button { width: 100%; }
}

const trains = [
  { destination: "Harbor City", time: "08:10", platform: "1" },
  { destination: "Pine Ridge", time: "08:20", platform: "3" },
  { destination: "Old Town", time: "08:35", platform: "2" },
  { destination: "Silver Lake", time: "08:50", platform: "4" },
  { destination: "Cedar Falls", time: "09:05", platform: "1" },
  { destination: "Northpoint", time: "09:25", platform: "5" }
];

let minutes = 8 * 60;
const clock = document.querySelector("#clock");
const departures = document.querySelector("#departures");
const announcement = document.querySelector("#announcement");

function formatTime(value) {
  const hour = Math.floor(value / 60) % 24;
  const minute = value % 60;
  return `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`;
}

function render() {
  clock.textContent = formatTime(minutes);
  const nextIndex = trains.findIndex(train => {
    const [hour, minute] = train.time.split(":").map(Number);
    return hour * 60 + minute > minutes;
  });

  departures.replaceChildren(...trains.map((train, index) => {
    const [hour, minute] = train.time.split(":").map(Number);
    const departed = hour * 60 + minute <= minutes;
    const row = document.createElement("tr");
    if (departed) row.classList.add("departed");
    else if (index === nextIndex) row.classList.add("next");

    const values = [train.destination, train.time, train.platform, departed ? "DEPARTED" : index === nextIndex ? "NEXT TRAIN" : "ON TIME"];
    values.forEach((value, cellIndex) => {
      const cell = document.createElement("td");
      cell.textContent = value;
      if (cellIndex === 3) cell.className = "status";
      row.append(cell);
    });
    return row;
  }));
}

document.querySelector("#advance").addEventListener("click", () => {
  minutes = (minutes + 5) % (24 * 60);
  render();
  announcement.textContent = `Station time advanced to ${formatTime(minutes)}.`;
});

render();
